use std::{cell::Cell,rc::Rc};
use jit_runtime::WasmtimeExecutor;
use wasm_vm_core::{Machine,RunOutcome,bus::{Bus,mmap::DRAM_BASE as BASE},dev::rtc::WallClock,session_clock::{SessionEffect,sources::{ObservationTape,ObservationRecord}}};
struct Clock{calls:Rc<Cell<u32>>,hostile:bool}
impl WallClock for Clock{fn now_ns(&self)->u64{assert!(!self.hostile,"replay read host RTC");self.calls.set(self.calls.get()+1);123}}
fn board()->(Machine,Rc<Cell<u32>>){let mut m=Machine::new(1<<20);m.enable_clint(5);m.enable_plic();let calls=Rc::new(Cell::new(0));m.enable_rtc(Box::new(Clock{calls:calls.clone(),hostile:false}));let words=[0x00108093u32,0x00310113,0x00518193,0x00720213,0x00b28293,0xfedff06f];for(i,w)in words.into_iter().enumerate(){m.bus_mut().store32(BASE+i as u64*4,w).unwrap();}m.hart_mut().regs.pc=BASE;m.set_block_cache(true);m.set_interrupt_batching(true);m.set_executor(Box::new(WasmtimeExecutor::new()));m.set_hotness_threshold(1);m.set_jit(true);m.start_session_clock(1).unwrap();assert_eq!(m.run(384),RunOutcome::MaxInstrs);assert!(m.executor().unwrap().is_compiled(BASE));m.bus_mut().store32(0x10100c,0x7fffffff).unwrap();m.bus_mut().store32(0x101008,0xffffffff).unwrap();calls.set(0);(m,calls)}
fn main(){let out=std::path::Path::new("target/evidence/e9-t11-verifier/jit-poll-refutation");std::fs::create_dir_all(out).unwrap();let(mut record,record_calls)=board();let policy=record.source_policy();record.start_session_sources(policy,None).unwrap();let initial=record.save_session_resume().unwrap();std::fs::write(out.join("initial.resume"),&initial).unwrap();assert_eq!(record.run_session_until(420,6),Ok(RunOutcome::MaxInstrs));while record.session_position().unwrap().transition<420{assert_eq!(record.run_session_until(420,6),Ok(RunOutcome::MaxInstrs));}let rows=record.take_session_deliveries().unwrap();let tape=ObservationTape{policy,records:rows.iter().map(|r|{let SessionEffect::Observation(value)=&r.effect else{panic!("not observation")};ObservationRecord{position:r.position,value:value.clone()}}).collect()};std::fs::write(out.join("record.observations"),tape.encode().unwrap()).unwrap();let record_final=record.save_session_resume().unwrap();std::fs::write(out.join("record.resume"),&record_final).unwrap();let(mut control,control_calls)=board();control.start_session_sources(policy,Some(tape.clone())).unwrap();assert_eq!(control.save_session_resume().unwrap(),initial);while control.session_position().unwrap().transition<420{assert_eq!(control.run_session_until(420,6),Ok(RunOutcome::MaxInstrs));}assert_eq!(control.take_session_deliveries().unwrap(),rows);control.finish_session_source_replay().unwrap();assert_eq!(control.save_session_resume().unwrap(),record_final);assert_eq!(control_calls.get(),0);println!("same-quantum6 control replay HELD: initial+final frames and receipts identical; RTC calls0");println!("record calls={} positions={:?} jit_executed={}",record_calls.get(),tape.records.iter().map(|r|(r.position.transition,r.position.sequence)).collect::<Vec<_>>(),record.executor().unwrap().executed_blocks());let(mut replay,replay_calls)=board();replay.start_session_sources(policy,Some(tape)).unwrap();assert_eq!(replay.save_session_resume().unwrap(),initial);let mut results=vec![];for _ in 0..36{let result=replay.run_session_until(420,1);results.push((replay.session_position().unwrap(),result));if !matches!(result,Ok(RunOutcome::MaxInstrs)){break;}}let failure=format!("replay calls={} results={results:?}\n",replay_calls.get());std::fs::write(out.join("replay-position.txt"),&failure).unwrap();println!("{failure}");assert!(results.iter().all(|(_,r)|matches!(r,Ok(RunOutcome::MaxInstrs))),"source tape diverged under admitted warmed JIT and different quantum");}
